pub const WOP_DIV: u8 = 6;

pub fn module_func() -> &'static str {
    return "(module)";
}

pub fn module_line() -> u32 {
    return 0;
}

pub fn carrier(name: &[u8]) -> u8 {
    let mut b: u8 = valtype_byte(name);
    if (b != 0) {
        return b;
    }
    if ((((name.len() == 3) && (name[0] == b'u')) && (name[1] == b'6')) && (name[2] == b'4')) {
        return VT_I64;
    }
    if ((((name.len() == 3) && (name[0] == b'p')) && (name[1] == b't')) && (name[2] == b'r')) {
        return 0;
    }
    if (((((name.len() == 4) && (name[0] == b'i')) && (name[1] == b'1')) && (name[2] == b'2')) && (name[3] == b'8')) {
        return 0;
    }
    return VT_I32;
}

pub fn carries(name: &[u8]) -> bool {
    return (carrier(name) != 0);
}

pub fn arith_debug_name(op: u8) -> &'static str {
    if (op == 0) {
        return "Add";
    }
    if (op == 1) {
        return "Sub";
    }
    if (op == 2) {
        return "Mul";
    }
    if (op == 3) {
        return "AddW";
    }
    if (op == 4) {
        return "SubW";
    }
    if (op == 5) {
        return "MulW";
    }
    if (op == 6) {
        return "Div";
    }
    if (op == 7) {
        return "DivW";
    }
    if (op == 8) {
        return "Rem";
    }
    if (op == 9) {
        return "And";
    }
    if (op == 10) {
        return "Or";
    }
    if (op == 11) {
        return "Xor";
    }
    if (op == 12) {
        return "Shl";
    }
    if (op == 13) {
        return "Shr";
    }
    if (op == 14) {
        return "ShlW";
    }
    return "ShrW";
}

pub fn refusal_construct(code: u8) -> &'static str {
    if (code == REF_VOID_PUB_FN) {
        return "void pub fn";
    }
    if (code == REF_PTR_RETURN) {
        return "ptr return";
    }
    if (code == REF_I128_RETURN) {
        return "i128 return";
    }
    if ((code == REF_FN_BODY_CONST) || (code == REF_FN_BODY_SELECT)) {
        return "fn body";
    }
    if (code == REF_FN_PARAMETERS) {
        return "fn parameters";
    }
    if (code == REF_FN_RETURN_TYPE) {
        return "fn return type";
    }
    if (code == REF_LOCAL_VARIABLE) {
        return "local variable";
    }
    if (code == REF_ARITHMETIC_OP) {
        return "arithmetic op";
    }
    if (code == REF_EXPRESSION_KIND) {
        return "expression kind";
    }
    if ((code == REF_IF_CONDITION_CMP) || (code == REF_IF_CONDITION_SHAPE)) {
        return "if condition";
    }
    if (code == REF_MODULE) {
        return "module";
    }
    return "";
}

pub fn refusal_detail(code: u8) -> &'static str {
    if (code == REF_VOID_PUB_FN) {
        return "the wasm32 emitter exports fns that return a scalar";
    }
    if (code == REF_FN_BODY_CONST) {
        return "the wasm32 emitter lowers a single `return <const>;` body only";
    }
    if (code == REF_LOCAL_VARIABLE) {
        return "the wasm32 emitter reads the fn's parameters only";
    }
    if (code == REF_EXPRESSION_KIND) {
        return "the wasm32 emitter lowers parameters, i32 constants, + - * / and == != < <= > >= only";
    }
    if (code == REF_FN_BODY_SELECT) {
        return "the wasm32 emitter lowers `return <expr>;` or `if (<param> == 0) { return <const>; } return <const>;` only";
    }
    if (code == REF_IF_CONDITION_CMP) {
        return "the wasm32 emitter compares a parameter against 0 (eqz, the law's comparison floor) only";
    }
    if (code == REF_IF_CONDITION_SHAPE) {
        return "the wasm32 emitter compares a parameter against 0 only (`== 0`, eqz's exact shape)";
    }
    if (code == REF_MODULE) {
        return "no pub fn whose body the wasm32 emitter lowers (a constant leaf, or an expression over i32 parameters and constants)";
    }
    return "";
}

pub fn uncarried_return_detail(out: &mut [u8], at: usize, ty: &[u8]) -> usize {
    let mut n: usize = put_bytes(out, at, b"the wasm32 emitter exports scalar returns, `");
    n = put_bytes(out, n, ty);
    return put_bytes(out, n, b"` here");
}

pub fn i32_params_detail(out: &mut [u8], at: usize, ty: &[u8]) -> usize {
    let mut n: usize = put_bytes(out, at, b"the wasm32 emitter carries i32 parameters, `");
    n = put_bytes(out, n, ty);
    return put_bytes(out, n, b"` here");
}

pub fn i32_results_detail(out: &mut [u8], at: usize, ty: &[u8]) -> usize {
    let mut n: usize = put_bytes(out, at, b"the wasm32 emitter carries i32 results here, `");
    n = put_bytes(out, n, ty);
    return put_bytes(out, n, b"` instead");
}

pub fn arith_op_detail(out: &mut [u8], at: usize, op: u8) -> usize {
    let mut n: usize = put_bytes(out, at, b"the wasm32 emitter lowers + - * / on the i32 carrier, `");
    n = put_bytes(out, n, arith_debug_name(op).as_bytes());
    return put_bytes(out, n, b"` here");
}

pub fn put_u32_dec(out: &mut [u8], at: usize, v: u32) -> usize {
    let mut n: usize = dec_len((v as usize));
    let mut x: u32 = v;
    let mut i: usize = n;
    while (i > 0) {
        i = (i - 1);
        out[((at + i)) as usize] = ((0x30 + (x % 10)) as _);
        x = (x / 10);
    }
    return (at + n);
}

pub fn refusal_message(out: &mut [u8], at: usize, construct: &[u8], line: u32, func: &[u8], detail: &[u8]) -> usize {
    let mut n: usize = put_bytes(out, at, b"unsupported construct ");
    n = put_bytes(out, n, construct);
    n = put_bytes(out, n, b" at line ");
    n = put_u32_dec(out, n, line);
    n = put_bytes(out, n, b" (fn ");
    n = put_bytes(out, n, func);
    n = put_bytes(out, n, b": ");
    n = put_bytes(out, n, detail);
    return put_bytes(out, n, b")");
}

pub fn refused_local_variable(var_idx: u32, nparams: u32) -> bool {
    return (var_idx >= nparams);
}

pub fn refused_arithmetic_op(op: u8) -> bool {
    return ((((op != WOP_ADD) && (op != WOP_SUB)) && (op != WOP_MUL)) && (op != WOP_DIV));
}

pub fn refused_expression_kind(kind: u8) -> bool {
    return ((((kind != EK_CONST) && (kind != EK_VAR)) && (kind != EK_ARITH)) && (kind != EK_CMP));
}

pub fn expr_refusal(kind: u8, var_idx: u32, op: u8, nparams: u32, lhs_r: u8, rhs_r: u8) -> u8 {
    if (kind == EK_CONST) {
        return REF_OK;
    }
    if (kind == EK_VAR) {
        if refused_local_variable(var_idx, nparams) {
            return REF_LOCAL_VARIABLE;
        }
        return REF_OK;
    }
    if (kind == EK_ARITH) {
        if refused_arithmetic_op(op) {
            return REF_ARITHMETIC_OP;
        }
        if (lhs_r != REF_OK) {
            return lhs_r;
        }
        return rhs_r;
    }
    if (kind == EK_CMP) {
        if (lhs_r != REF_OK) {
            return lhs_r;
        }
        return rhs_r;
    }
    return REF_EXPRESSION_KIND;
}

pub fn select_refusal(els_len: usize, then_ok: bool, arms_const: bool, cond_eq: bool, cond_shape: bool, pv: u32, nparams: u32) -> u8 {
    if (els_len != 0) {
        return REF_FN_BODY_SELECT;
    }
    if !(then_ok) {
        return REF_FN_BODY_SELECT;
    }
    if !(arms_const) {
        return REF_FN_BODY_SELECT;
    }
    if !(cond_eq) {
        return REF_IF_CONDITION_CMP;
    }
    if !(cond_shape) {
        return REF_IF_CONDITION_SHAPE;
    }
    if refused_local_variable(pv, nparams) {
        return REF_FN_BODY_SELECT;
    }
    return REF_OK;
}

pub fn fn_refusal(is_test: bool, is_pub: bool, has_ret: bool, ret_name: &[u8], nparams: u32, params_all_i32: bool, body_shape: u8, body_r: u8) -> u8 {
    if (is_test || !(is_pub)) {
        return REF_SKIP;
    }
    if !(has_ret) {
        return REF_VOID_PUB_FN;
    }
    if (nparams == 0) {
        if (carrier(ret_name) == 0) {
            if ((((ret_name.len() == 3) && (ret_name[0] == b'p')) && (ret_name[1] == b't')) && (ret_name[2] == b'r')) {
                return REF_PTR_RETURN;
            }
            return REF_I128_RETURN;
        }
        if (body_shape != BS_CONST_RETURN) {
            return REF_FN_BODY_CONST;
        }
        return REF_OK;
    }
    if !(params_all_i32) {
        return REF_FN_PARAMETERS;
    }
    let mut c: u8 = carrier(ret_name);
    if (c == 0) {
        if ((((ret_name.len() == 3) && (ret_name[0] == b'p')) && (ret_name[1] == b't')) && (ret_name[2] == b'r')) {
            return REF_PTR_RETURN;
        }
        return REF_I128_RETURN;
    }
    if (c != VT_I32) {
        return REF_FN_RETURN_TYPE;
    }
    if ((body_shape == BS_RETURN_EXPR) || (body_shape == BS_SELECT)) {
        return body_r;
    }
    return REF_FN_BODY_SELECT;
}

pub fn refused_module(exports: usize) -> bool {
    return (exports == 0);
}

pub fn sleb_value(t: &[u8]) -> i64 {
    let mut result: i64 = 0;
    let mut ones: i64 = (0 - 1);
    let mut shift: u32 = 0;
    let mut i: usize = 0;
    while (i < t.len()) {
        let mut b: u8 = t[(i) as usize];
        result = (result | (((b & 0x7F) as i64) << shift));
        i = (i + 1);
        if ((b & 0x80) == 0) {
            if (((b & 0x40) != 0) && (shift < 57)) {
                result = (result | (ones << (shift + 7)));
            }
            return result;
        }
        shift = (shift + 7);
    }
    return result;
}

pub fn i32_signed_image(v: u64) -> i32 {
    let mut lo: u64 = (v & 0xFFFFFFFF);
    let mut x: i64 = (lo as _);
    if (lo >= 0x80000000) {
        x = (x - 0x100000000);
    }
    return (x as _);
}

pub fn i64_signed_image(v: u64) -> i64 {
    let mut lo: u64 = (v & 0x7FFFFFFFFFFFFFFF);
    let mut x: i64 = (lo as _);
    if (v >= 0x8000000000000000) {
        x = ((x - 0x4000000000000000) - 0x4000000000000000);
    }
    return x;
}

pub fn f32_const_bits(v: u64) -> u32 {
    return ((v & 0xFFFFFFFF) as _);
}

pub fn const_insn(out: &mut [u8], at: usize, ty: &[u8], v: u64) -> usize {
    let mut c: u8 = carrier(ty);
    if (c == 0) {
        return at;
    }
    if (c == VT_F32) {
        return f32_const(out, at, f32_const_bits(v));
    }
    if (c == VT_F64) {
        return f64_const(out, at, v);
    }
    if (c == VT_I64) {
        return i64_const(out, at, i64_signed_image(v));
    }
    return i32_const(out, at, i32_signed_image(v));
}

pub fn arith_opcode(op: u8) -> u8 {
    if (op == WOP_ADD) {
        return OP_I32_ADD;
    }
    if (op == WOP_SUB) {
        return OP_I32_SUB;
    }
    if (op == WOP_MUL) {
        return OP_I32_MUL;
    }
    if (op == WOP_DIV) {
        return OP_I32_DIV_U;
    }
    return 0;
}

pub fn cmp_opcode(op: u8) -> u8 {
    if (op == 0) {
        return OP_I32_EQ;
    }
    if (op == 1) {
        return OP_I32_NE;
    }
    if (op == 2) {
        return OP_I32_LT_S;
    }
    if (op == 3) {
        return OP_I32_LE_S;
    }
    if (op == 4) {
        return OP_I32_GT_S;
    }
    if (op == 5) {
        return OP_I32_GE_S;
    }
    return 0;
}

pub fn lower_expr_node(out: &mut [u8], at: usize, kind: u8, v: u64, var_idx: u32, op: u8) -> usize {
    if (kind == EK_CONST) {
        return i32_const(out, at, i32_signed_image(v));
    }
    if (kind == EK_VAR) {
        return local_get(out, at, var_idx);
    }
    if (kind == EK_ARITH) {
        let mut oc: u8 = arith_opcode(op);
        if (oc == 0) {
            return at;
        }
        out[(at) as usize] = oc;
        return (at + 1);
    }
    if (kind == EK_CMP) {
        let mut oc: u8 = cmp_opcode(op);
        if (oc == 0) {
            return at;
        }
        out[(at) as usize] = oc;
        return (at + 1);
    }
    return at;
}

pub fn select_body(out: &mut [u8], at: usize, x: u64, y: u64, pv: u32) -> usize {
    let mut n: usize = i32_const(out, at, i32_signed_image(x));
    n = i32_const(out, n, i32_signed_image(y));
    n = local_get(out, n, pv);
    n = i32_eqz(out, n);
    return select(out, n);
}

pub const FACT_ROW: usize = 48;

pub const NODE_ROW: usize = 16;

pub const FF_TEST: u32 = 0x01;

pub const FF_PUB: u32 = 0x02;

pub const FF_RET: u32 = 0x04;

pub const FF_PARAMS_I32: u32 = 0x08;

pub fn fact_put(out: &mut [u8], at: usize, flags: u32, name_off: u32, name_len: u32, nparams: u32, ret_off: u32, ret_len: u32, shape: u8, body_r: u8, payload_off: u32, payload_len: u32, line: u32) -> usize {
    let mut n: usize = put_u32le(out, at, flags);
    n = put_u32le(out, n, name_off);
    n = put_u32le(out, n, name_len);
    n = put_u32le(out, n, nparams);
    n = put_u32le(out, n, ret_off);
    n = put_u32le(out, n, ret_len);
    n = put_u32le(out, n, (shape as u32));
    n = put_u32le(out, n, (body_r as u32));
    n = put_u32le(out, n, payload_off);
    n = put_u32le(out, n, payload_len);
    n = put_u32le(out, n, line);
    return put_u32le(out, n, 0);
}

pub fn fact_flags(facts: &[u8], i: usize) -> u32 {
    return get_u32le(facts, (FACT_ROW * i));
}

pub fn fact_name_off(facts: &[u8], i: usize) -> u32 {
    return get_u32le(facts, ((FACT_ROW * i) + 4));
}

pub fn fact_name_len(facts: &[u8], i: usize) -> u32 {
    return get_u32le(facts, ((FACT_ROW * i) + 8));
}

pub fn fact_nparams(facts: &[u8], i: usize) -> u32 {
    return get_u32le(facts, ((FACT_ROW * i) + 12));
}

pub fn fact_ret_off(facts: &[u8], i: usize) -> u32 {
    return get_u32le(facts, ((FACT_ROW * i) + 16));
}

pub fn fact_ret_len(facts: &[u8], i: usize) -> u32 {
    return get_u32le(facts, ((FACT_ROW * i) + 20));
}

pub fn fact_shape(facts: &[u8], i: usize) -> u8 {
    return ((get_u32le(facts, ((FACT_ROW * i) + 24)) & 0xFF) as _);
}

pub fn fact_body_r(facts: &[u8], i: usize) -> u8 {
    return ((get_u32le(facts, ((FACT_ROW * i) + 28)) & 0xFF) as _);
}

pub fn fact_payload_off(facts: &[u8], i: usize) -> u32 {
    return get_u32le(facts, ((FACT_ROW * i) + 32));
}

pub fn fact_payload_len(facts: &[u8], i: usize) -> u32 {
    return get_u32le(facts, ((FACT_ROW * i) + 36));
}

pub fn fact_line(facts: &[u8], i: usize) -> u32 {
    return get_u32le(facts, ((FACT_ROW * i) + 40));
}

pub fn fact_rows(facts: &[u8]) -> usize {
    return (facts.len() / FACT_ROW);
}

pub fn node_put(out: &mut [u8], at: usize, kind: u8, op: u8, var_idx: u32, v: u64) -> usize {
    out[(at) as usize] = kind;
    out[((at + 1)) as usize] = op;
    out[((at + 2)) as usize] = 0;
    out[((at + 3)) as usize] = 0;
    let mut n: usize = put_u32le(out, (at + 4), var_idx);
    n = put_u32le(out, n, ((v & 0xFFFFFFFF) as _));
    return put_u32le(out, n, (((v >> 32) & 0xFFFFFFFF) as _));
}

pub fn node_kind(nodes: &[u8], j: usize) -> u8 {
    return nodes[((NODE_ROW * j)) as usize];
}

pub fn node_op(nodes: &[u8], j: usize) -> u8 {
    return nodes[(((NODE_ROW * j) + 1)) as usize];
}

pub fn node_var(nodes: &[u8], j: usize) -> u32 {
    return get_u32le(nodes, ((NODE_ROW * j) + 4));
}

pub fn node_v(nodes: &[u8], j: usize) -> u64 {
    let mut lo: u64 = (get_u32le(nodes, ((NODE_ROW * j) + 8)) as u64);
    let mut hi: u64 = (get_u32le(nodes, ((NODE_ROW * j) + 12)) as u64);
    return (lo | (hi << 32));
}

pub fn facts_ok(facts: &[u8], strings: &[u8], nodes: &[u8]) -> bool {
    if ((facts.len() % FACT_ROW) != 0) {
        return false;
    }
    let mut i: usize = 0;
    while (i < fact_rows(facts)) {
        if ((fact_name_off(facts, i) + fact_name_len(facts, i)) > (strings.len() as u32)) {
            return false;
        }
        if ((fact_ret_off(facts, i) + fact_ret_len(facts, i)) > (strings.len() as u32)) {
            return false;
        }
        let mut po: usize = (fact_payload_off(facts, i) as usize);
        let mut pl: usize = (fact_payload_len(facts, i) as usize);
        if ((po + (pl * NODE_ROW)) > nodes.len()) {
            return false;
        }
        i = (i + 1);
    }
    return true;
}

pub fn fn_body_bytes(out: &mut [u8], at: usize, shape: u8, ret_name: &[u8], payload_off: u32, payload_len: u32, nodes: &[u8]) -> usize {
    let mut n: usize = at;
    if (shape == BS_CONST_RETURN) {
        n = const_insn(out, at, ret_name, node_v(nodes, (payload_off as usize)));
    } else {
        if (shape == BS_RETURN_EXPR) {
            let mut j: usize = 0;
            while (j < (payload_len as usize)) {
                let mut r: usize = ((payload_off as usize) + j);
                n = lower_expr_node(out, n, node_kind(nodes, r), node_v(nodes, r), node_var(nodes, r), node_op(nodes, r));
                j = (j + 1);
            }
        } else {
            if (shape == BS_SELECT) {
                if (payload_len != 3) {
                    return 0;
                }
                let mut p: usize = (payload_off as usize);
                n = select_body(out, at, node_v(nodes, p), node_v(nodes, (p + 1)), node_var(nodes, (p + 2)));
            } else {
                return 0;
            }
        }
    }
    return end(out, n);
}

pub fn walk_refusal(facts: &[u8], strings: &[u8], nodes: &[u8]) -> u8 {
    if !(facts_ok(facts, strings, nodes)) {
        return REF_MODULE;
    }
    let mut admitted: usize = 0;
    let mut i: usize = 0;
    while (i < fact_rows(facts)) {
        let mut fl: u32 = fact_flags(facts, i);
        let mut ro: usize = (fact_ret_off(facts, i) as usize);
        let mut rl: usize = (fact_ret_len(facts, i) as usize);
        let mut r: u8 = fn_refusal(((fl & FF_TEST) != 0), ((fl & FF_PUB) != 0), ((fl & FF_RET) != 0), &strings[(ro) as usize..((ro + rl)) as usize], fact_nparams(facts, i), ((fl & FF_PARAMS_I32) != 0), fact_shape(facts, i), fact_body_r(facts, i));
        if (r != REF_SKIP) {
            if (r != REF_OK) {
                return r;
            }
            admitted = (admitted + 1);
        }
        i = (i + 1);
    }
    if (admitted == 0) {
        return REF_MODULE;
    }
    return REF_OK;
}

pub fn walk_refusal_row(facts: &[u8], strings: &[u8], nodes: &[u8]) -> usize {
    if !(facts_ok(facts, strings, nodes)) {
        return fact_rows(facts);
    }
    let mut i: usize = 0;
    while (i < fact_rows(facts)) {
        let mut fl: u32 = fact_flags(facts, i);
        let mut ro: usize = (fact_ret_off(facts, i) as usize);
        let mut rl: usize = (fact_ret_len(facts, i) as usize);
        let mut r: u8 = fn_refusal(((fl & FF_TEST) != 0), ((fl & FF_PUB) != 0), ((fl & FF_RET) != 0), &strings[(ro) as usize..((ro + rl)) as usize], fact_nparams(facts, i), ((fl & FF_PARAMS_I32) != 0), fact_shape(facts, i), fact_body_r(facts, i));
        if ((r != REF_SKIP) && (r != REF_OK)) {
            return i;
        }
        i = (i + 1);
    }
    return fact_rows(facts);
}

pub fn walk_prog(names_out: &mut [u8], descs_out: &mut [u8], bodies_out: &mut [u8], facts: &[u8], strings: &[u8], nodes: &[u8]) -> usize {
    if (walk_refusal(facts, strings, nodes) != REF_OK) {
        return 0;
    }
    let mut nn: usize = 0;
    let mut bn: usize = 0;
    let mut k: usize = 0;
    let mut dn: usize = 0;
    let mut i: usize = 0;
    while (i < fact_rows(facts)) {
        let mut fl: u32 = fact_flags(facts, i);
        if (((fl & FF_TEST) == 0) && ((fl & FF_PUB) != 0)) {
            let mut nl: usize = (fact_name_len(facts, i) as usize);
            let mut pl: usize = (fact_payload_len(facts, i) as usize);
            if ((nn + nl) > names_out.len()) {
                return 0;
            }
            if (((k + 1) * DESC_ROW) > descs_out.len()) {
                return 0;
            }
            let mut worst: usize = ((pl * 6) + 1);
            if (fact_shape(facts, i) == BS_CONST_RETURN) {
                worst = ((pl * 11) + 1);
            }
            if (fact_shape(facts, i) == BS_SELECT) {
                worst = ((pl * 6) + 3);
            }
            if ((bn + worst) > bodies_out.len()) {
                return 0;
            }
            let mut a: usize = (fact_name_off(facts, i) as usize);
            nn = put_bytes(names_out, nn, &strings[(a) as usize..((a + nl)) as usize]);
            let mut ro: usize = (fact_ret_off(facts, i) as usize);
            let mut rl: usize = (fact_ret_len(facts, i) as usize);
            let mut bo: usize = bn;
            bn = fn_body_bytes(bodies_out, bn, fact_shape(facts, i), &strings[(ro) as usize..((ro + rl)) as usize], fact_payload_off(facts, i), fact_payload_len(facts, i), nodes);
            dn = desc_put(descs_out, dn, ((nn - nl) as u32), (nl as u32), fact_nparams(facts, i), carrier(&strings[(ro) as usize..((ro + rl)) as usize]), (bo as u32), ((bn - bo) as u32));
            k = (k + 1);
        }
        i = (i + 1);
    }
    if (k == 0) {
        return 0;
    }
    return dn;
}

pub fn walk_names_len(descs: &[u8]) -> usize {
    let mut k: usize = desc_count(descs);
    if (k == 0) {
        return 0;
    }
    let mut a: usize = (desc_name_off(descs, (k - 1)) as usize);
    return (a + (desc_name_len(descs, (k - 1)) as usize));
}

pub fn walk_bodies_len(descs: &[u8]) -> usize {
    let mut k: usize = desc_count(descs);
    if (k == 0) {
        return 0;
    }
    let mut a: usize = (desc_body_off(descs, (k - 1)) as usize);
    return (a + (desc_body_len(descs, (k - 1)) as usize));
}

pub const OP_I32_EQ: u8 = 0x46;

pub const OP_I32_NE: u8 = 0x47;

pub const OP_I32_LT_S: u8 = 0x48;

pub const OP_I32_GT_S: u8 = 0x4A;

pub const OP_I32_LE_S: u8 = 0x4C;

pub const OP_I32_GE_S: u8 = 0x4E;

pub fn i32_eq(out: &mut [u8], at: usize) -> usize {
    out[(at) as usize] = OP_I32_EQ;
    return (at + 1);
}

pub fn i32_ne(out: &mut [u8], at: usize) -> usize {
    out[(at) as usize] = OP_I32_NE;
    return (at + 1);
}

pub fn i32_lt_s(out: &mut [u8], at: usize) -> usize {
    out[(at) as usize] = OP_I32_LT_S;
    return (at + 1);
}

pub fn i32_gt_s(out: &mut [u8], at: usize) -> usize {
    out[(at) as usize] = OP_I32_GT_S;
    return (at + 1);
}

pub fn i32_le_s(out: &mut [u8], at: usize) -> usize {
    out[(at) as usize] = OP_I32_LE_S;
    return (at + 1);
}

pub fn i32_ge_s(out: &mut [u8], at: usize) -> usize {
    out[(at) as usize] = OP_I32_GE_S;
    return (at + 1);
}

pub fn eqz_fold(op: u8, lhs_zero: bool, rhs_zero: bool) -> u8 {
    if (!(lhs_zero) && !(rhs_zero)) {
        return 0;
    }
    if (op == 0) {
        return 1;
    }
    if (op == 1) {
        return 2;
    }
    return 0;
}

pub fn eqz_uses(out: &mut [u8], at: usize, uses: u8) -> usize {
    let mut n: usize = at;
    let mut i: u8 = 0;
    while (i < uses) {
        n = i32_eqz(out, n);
        i = (i + 1);
    }
    return n;
}

pub const AT: u8 = 64;

pub const ROW: usize = 16;

pub fn dec_len(v: usize) -> usize {
    let mut n: usize = 1;
    let mut x: usize = v;
    while (x >= 10) {
        x = (x / 10);
        n = (n + 1);
    }
    return n;
}

pub fn exported(names: &[u8], fns: &[u8], i: usize, at: usize) -> bool {
    if (fn_at(fns, i) == 0) {
        return false;
    }
    return ((names[(at) as usize] != 0) && (names[(at) as usize] != AT));
}

pub fn fn_at(fns: &[u8], i: usize) -> usize {
    return get_u64(fns, (ROW * i));
}

pub fn get_u64(t: &[u8], at: usize) -> usize {
    let mut v: usize = 0;
    let mut i: usize = 8;
    while (i > 0) {
        i = (i - 1);
        v = ((v << 8) | (t[((at + i)) as usize] as usize));
    }
    return v;
}

pub fn name_len(names: &[u8], at: usize) -> usize {
    let mut n: usize = 0;
    while (names[((at + n)) as usize] != 0) {
        n = (n + 1);
    }
    return n;
}

pub fn put_bytes(out: &mut [u8], at: usize, src: &[u8]) -> usize {
    let mut i: usize = 0;
    while (i < src.len()) {
        out[((at + i)) as usize] = src[(i) as usize];
        i = (i + 1);
    }
    return (at + src.len());
}

